def even_odd_count(num):
    num = abs(num)  # Consider only the absolute value of the number
    even_count = 0
    odd_count = 0

    for digit in str(num):  # Convert the number to a string to iterate over each digit
        if int(digit) % 2 == 0:
            even_count += 1
        else:
            odd_count += 1

    return (even_count, odd_count)

